"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/usage-budget/variants/01-overview";
export interface ArtemisUsageBudgetProps { className?: string;  }
export function ArtemisUsageBudget({ className }: ArtemisUsageBudgetProps) { return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><Variant0/></ArtemisScope>; }

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ArtemisDigitSwap } from "../../../foundations/digit-swap";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
export default function UsageBudgetOverview() {
    const used = 55.8;
    const reduce = useReducedMotion();
    const [budget, setBudget] = useState(100);
    const [previousFilled, setPreviousFilled] = useState(22);
    const [direction, setDirection] = useState<"up" | "down">("up");
    const percent = Math.round(used / budget * 100);
    const filled = Math.min(40, Math.round(percent * 40 / 100));
    const adjust = (amount: number) => {
        setPreviousFilled(filled);
        setDirection(amount > 0 ? "up" : "down");
        setBudget(current => Math.max(25, current + amount));
    };
    return (<>
      <section aria-label="Usage budget" className="art:w-full art:max-w-lg art:rounded-3xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
        <header className="art:flex art:items-center art:justify-between">
          <h2 className="art:text-4xl art:font-medium">
            {"Usage budget"}
          </h2>
          <span className="art:text-xs art:text-muted-foreground">
            {"September"}
          </span>
        </header>
        <div className="art:my-7 art:flex art:items-end art:justify-between art:gap-4">
          <div>
            <p className="art:mb-2 art:text-sm art:text-muted-foreground">
              {"Total used"}
            </p>
            <div className="art:flex art:items-center art:gap-2">
              <ArtemisDigitSwap value="$55.80" className="art:text-4xl art:font-medium art:tracking-tight"/>
              <span className="art:flex art:items-center art:gap-1 art:text-sm art:text-muted-foreground">
                {"/ "}
                <ArtemisDigitSwap value={`$${budget}`} direction={direction}/>
              </span>
            </div>
          </div>
          <span className="art:flex art:size-11 art:items-center art:justify-center art:rounded-full art:bg-muted">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-gauge art:size-5" aria-hidden="true">
              <path d="m12 14 4-4"/>
              <path d="M3.34 19a10 10 0 1 1 17.32 0"/>
            </svg>
          </span>
        </div>
        <div className="art:flex art:h-9 art:items-center art:gap-1" aria-hidden="true">
          {Array.from({ length: 40 }, (_, index) => (<span key={index} className="art:relative art:h-full art:min-w-0 art:flex-1 art:overflow-hidden art:rounded-full art:bg-primary/10">
              <motion.span className="art:absolute art:inset-0 art:origin-bottom art:rounded-full art:bg-primary" initial={{ opacity: 0, scaleY: 0 }} animate={{ opacity: index < filled ? 1 : 0, scaleY: index < filled ? 1 : 0 }} transition={reduce ? { duration: 0 } : { duration: 0.24, delay: index >= Math.min(previousFilled, filled) && index < Math.max(previousFilled, filled) ? (filled > previousFilled ? index - previousFilled : previousFilled - 1 - index) * 0.025 : 0, ease: ARTEMIS_EASE_OUT }}/>
            </span>))}
        </div>
        <p className="art:mt-3 art:text-xs art:text-muted-foreground">
          {budget < used ? `$${(used - budget).toFixed(2)} over budget` : `$${(budget - used).toFixed(2)} remaining this month \u00B7 ${percent}% used`}
        </p>
        <dl className="art:my-6 art:divide-y art:divide-border">
          <div className="art:flex art:items-center art:justify-between art:gap-4 art:py-3">
            <dt>
              <span className="art:block art:text-sm art:font-medium">
                {"Model inference"}
              </span>
              <span className="art:text-xs art:text-muted-foreground">
                {"1.8M tokens across 3 models"}
              </span>
            </dt>
            <dd className="art:text-sm art:tabular-nums">
              {"$"}
              {"38.40"}
            </dd>
          </div>
          <div className="art:flex art:items-center art:justify-between art:gap-4 art:py-3">
            <dt>
              <span className="art:block art:text-sm art:font-medium">
                {"Tool calls"}
              </span>
              <span className="art:text-xs art:text-muted-foreground">
                {"420 searches and browser actions"}
              </span>
            </dt>
            <dd className="art:text-sm art:tabular-nums">
              {"$"}
              {"12.60"}
            </dd>
          </div>
          <div className="art:flex art:items-center art:justify-between art:gap-4 art:py-3">
            <dt>
              <span className="art:block art:text-sm art:font-medium">
                {"Knowledge storage"}
              </span>
              <span className="art:text-xs art:text-muted-foreground">
                {"2.4 GB indexed"}
              </span>
            </dt>
            <dd className="art:text-sm art:tabular-nums">
              {"$"}
              {"4.80"}
            </dd>
          </div>
        </dl>
        <div className="art:flex art:items-center art:justify-between art:gap-4 art:border-t art:border-border art:pt-4">
          <div>
            <p className="art:text-sm art:font-medium">
              {"Monthly limit"}
            </p>
            <p className="art:text-xs art:text-muted-foreground">
              {"Adjust in $25 increments"}
            </p>
          </div>
          <div className="art:flex art:items-center art:gap-3">
            <ArtemisButton variant="ghost" size="icon" className="art:size-9 art:border art:border-border art:h-9" aria-label="Decrease budget" onClick={() => adjust(-25)} disabled={budget <= 25}>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-minus art:size-4" aria-hidden="true">
                <path d="M5 12h14"/>
              </svg>
            </ArtemisButton>
            <output className="art:flex art:h-9 art:min-w-12 art:items-center art:justify-center art:text-sm art:leading-none art:tabular-nums">
              <ArtemisDigitSwap value={`$${budget}`} direction={direction}/>
            </output>
            <ArtemisButton variant="ghost" size="icon" className="art:size-9 art:border art:border-border art:h-9" aria-label="Increase budget" onClick={() => adjust(25)}>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-plus art:size-4" aria-hidden="true">
                <path d="M5 12h14"/>
                <path d="M12 5v14"/>
              </svg>
            </ArtemisButton>
          </div>
        </div>
      </section>
    </>);
}
